let state,storage={persistent:true,warning:''},view='today',selectedDeck='',search='',filter='all',busy=false,focusBeforeModal=null,toastTimer,audioToken='',draftTimer,importModel=null,contextOnlyFavorites=true;
const themeColourDrafts={};
let libraryPage=0,contextSearch='',contextDeck='',contextLimit=100,settingsDraft={},settingsBaseline=null;
const pageScroll=new Map(),settingsKeys=['dailyGoal','newBatch','reviewBatch','rate','retention','dailyGoalEnabled','language','theme','font','voiceURI','motionMode','autoWord','autoExample','listening','showShortcutHints'];
