const locale=()=>({zh:'zh-CN',en:'en-GB',fr:'fr-FR'}[state?.settings.language]||'zh-CN');
const icon=(name)=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+({sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',book:'<path d="M3 4h5a5 5 0 0 1 4 2 5 5 0 0 1 4-2h5v15h-5a5 5 0 0 0-4 2 5 5 0 0 0-4-2H3zM12 6v15"/>',quote:'<path d="M4 5h16v12H9l-5 4zM8 9h8M8 13h5"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',audio:'<path d="M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="m11 5-7 7 7 7M4 12h16"/>',heart:'<path d="M12 20S2 14 2 8a5 5 0 0 1 10-1A5 5 0 0 1 22 8c0 6-10 12-10 12z"/>',edit:'<path d="m15 4 5 5M4 20l1-6L16 3l5 5-11 11z"/>',repeat:'<path d="M5 7h13l-3-3m3 3-3 3M19 17H6l3 3m-3-3 3-3"/>'}[name]||'')+'</svg>';
const btn=(label,action,kind='',extra='')=>'<button type="button" class="button '+kind+'" data-action="'+action+'" '+extra+'>'+label+'</button>';
const rows=()=>state.decks.flatMap(deck=>deck.words.map(word=>({word,deck})));
const findWord=id=>rows().find(x=>x.word.id===id);
const scoped=()=>rows().filter(x=>state.settings.studyDeckIds.includes(x.deck.id)&&!x.word.needsConfirmation);
const date=n=>n?new Date(n).toLocaleDateString(locale(),{month:'short',day:'numeric'}):'—';
function clearToasts(){clearTimeout(toastTimer);$('#toast').classList.remove('visible');const notice=$('#modal-toast');if(notice){notice.hidden=true;notice.textContent=''}}
function unsavedMessage(){return storage.persistent===false?(storage.warning||t('更改尚未保存到浏览器，请导出备份。','Changes are not saved in this browser. Export a backup.','Modifications non enregistrées dans le navigateur. Exportez une sauvegarde.')):''}
function toast(message){clearToasts();const warning=unsavedMessage(),modal=$('#modal'),inside=modal.open&&!modal.classList.contains('motion-closing'),target=inside?$('#modal-toast'):$('#toast');target.textContent=warning&&message!==warning?message+'\n'+warning:message;if(inside)target.hidden=false;else target.classList.add('visible');if(!warning)toastTimer=setTimeout(clearToasts,4200)}
function previewNote(){return t('预览数据 · 仅本次会话','Preview data · this session only','Données de démonstration · cette session')}
function savedToast(message){toast(PREVIEW?message+' · '+previewNote():unsavedMessage()||message)}
function syncSaveWarning(){
 const status=$('.storage-state');if(status)status.textContent=PREVIEW?previewNote():storage.persistent?(RELEASE?t('已在此浏览器保存','Saved in this browser','Enregistré dans ce navigateur'):t('实验存档 · 本地保存','Experimental · saved locally','Expérimental · enregistré')):t('临时使用 · 尚未保存','Temporary · not saved','Temporaire · non enregistré');
 const warning=unsavedMessage(),host=$('.study-shell')||$('.main');if(!host)return;
 let notice=host.querySelector('.live-save-warning');if(!warning){notice?.remove();return}
 // A persistent warning remains visible even when a dialog or another toast
 // closes. The ordinary page shell may already carry the same warning.
 if(!notice&&host.querySelector('.save-banner'))return;
 if(!notice){notice=document.createElement('div');notice.className='save-banner live-save-warning';notice.setAttribute('role','status');const header=host.querySelector('.study-top,.page-header');if(header)header.after(notice);else host.prepend(notice)}
 notice.innerHTML='<span>'+esc(warning)+'</span> '+btn(t('导出备份','Export backup','Exporter une sauvegarde'),'backup-full','small');
}
function report(error){console.error(error);toast(error.code==='REVISION_CONFLICT'?t('另一窗口已更新。请先导出本页数据，再载入最新存档。','Another tab updated the data. Export this tab before reloading.','Un autre onglet a modifié les données. Exportez cet onglet avant de recharger.'):t('操作未完成：','Could not complete: ','Opération impossible : ')+error.message)}
let changeQueue=Promise.resolve(),pendingChanges=0,navigationRevision=0,modalRevision=0,resetInProgress=false;
function change(fn,{renderAfter=true,snapshot=false,guard=null,recover=false,requirePersistent=false}={}){
 if(resetInProgress)return Promise.resolve(false);
 pendingChanges++;busy=true;
 const run=async()=>{try{
  // Read the revision and clone only after earlier writes finish. A queued
  // study action also proves it still belongs to the question it came from.
  if(resetInProgress||guard&&!guard(state))return false;
  const revision=state.revision;let next=D.cloneForChange?D.cloneForChange(state):clone(state),result=await fn(next);
  if(result===false)return false;if(result&&result.version===4)next=result;
  const saved=await D.save(next,{expectedRevision:revision,snapshot,recover});if(requirePersistent&&!saved.persistent)throw new Error(saved.warning||t('未能保存到浏览器，请重试。','Could not save in this browser. Try again.','Enregistrement impossible. Réessayez.'));state=saved.state;storage=saved;window.__vocabState=state;
  if(renderAfter)render();syncSaveWarning();if(!saved.persistent)toast(unsavedMessage());return true;
 }catch(error){report(error);return false}finally{pendingChanges--;busy=pendingChanges>0}};
 const operation=changeQueue.then(run,run);changeQueue=operation.then(()=>undefined,()=>undefined);return operation;
}
function studyIdentity(){return {sessionId:state.session?.id,token:state.session?.current?.token}}
function sameQuestion(s,key){return !!key.token&&s.session?.id===key.sessionId&&s.session?.current?.token===key.token&&!s.session.done}
function questionChange(fn,options={}){const key=studyIdentity();return change(fn,{...options,guard:s=>sameQuestion(s,key)&&(!options.guard||options.guard(s))})}
function contexts(word){const own=state.contexts[word.id];if(own)return own;return word.example?[{id:'base-'+word.id,text:word.example,translation:word.exampleZh||'',source:word.source||t('词条例句','Word example','Exemple du mot'),sourceUrl:'',author:'',license:'',audioUrl:'',audioId:'',type:'tts',favorite:false,origin:'default'}]:[]}
function contextAt(wordId,contextId){const item=findWord(wordId);return item?contexts(item.word).find(c=>c.id===contextId):null}
function highlight(text,word,explicit){const target=explicit||word.french||word.spell||word.masc;const safe=esc(text);if(!target)return safe;const re=esc(target).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');try{return safe.replace(new RegExp(re,'giu'),m=>'<mark>'+m+'</mark>')}catch(_){return safe}}
function mediaLabel(c){return c.audioId||c.audioUrl?(c.type==='original'?t('原声片段','Original recording','Extrait original'):c.type==='human'?t('真人朗读','Human voice','Voix humaine'):t('合成朗读','Synthetic voice','Voix de synthèse')):t('合成朗读','Synthetic voice','Voix de synthèse')}
function sourceLink(c){return c.sourceUrl&&/^https?:\/\//i.test(c.sourceUrl)?'<a href="'+esc(c.sourceUrl)+'" target="_blank" rel="noopener noreferrer">'+esc(c.source||t('来源','Source','Source'))+'</a>':esc(c.source||t('自有例句','Personal example','Exemple personnel'))}
function audioStatus(info){if(info.fallback&&info.state==='loading')toast(t('录音不可用，已改用合成朗读。','Recording unavailable; using synthetic speech.','Audio indisponible ; voix de synthèse utilisée.'));const el=$('#audio-status');if(['playing','loading'].includes(info.state)){el.textContent=(info.mode==='tts'?t('合成朗读','Synthetic voice','Voix de synthèse'):info.mode==='human'?t('真人朗读','Human voice','Voix humaine'):info.label||t('播放中','Playing','Lecture'))+' · '+t('点击停止','Click to stop','Cliquer pour arrêter');el.classList.add('visible')}else{el.classList.remove('visible');if(info.state==='error')toast(t('无法播放，请检查音频或设备语音。','Playback unavailable. Check the audio or device voices.','Lecture indisponible. Vérifiez le fichier ou les voix.'))}}
function speechText(word,form='headword'){if(form==='masc'||form==='fem')return word[form]||word.french;if(form==='both')return [word.masc,word.fem].filter(Boolean).join('. ')||word.french;const head=word.french||word.spell||word.masc||word.fem||'';if(word.hasGender&&word.masc&&word.fem){const parts=head.split(/\s*[/;；]\s*/);if(parts.length===2&&parts.every(p=>[E.normalize(word.masc),E.normalize(word.fem)].includes(E.normalize(p))))return parts.join('. ')}return head}
function genderAudio(word,hideWords=false){if(!word.hasGender)return '';return '<div class="gender-audio '+(hideWords?'prompt-genders':'')+'">'+[['masc',t('阳性','Masculine','Masculin')],['fem',t('阴性','Feminine','Féminin')]].filter(([form])=>word[form]).map(([form,label])=>'<button type="button" class="gender-voice" data-action="speak-form" data-id="'+esc(word.id)+'" data-form="'+form+'" aria-label="'+esc(t('朗读','Play','Écouter')+' '+label+(hideWords?'':' '+word[form]))+'"><span class="gender-label">'+label+'</span>'+(hideWords?'':'<span class="gender-form" lang="fr">'+esc(word[form])+'</span>')+icon('audio')+'</button>').join('')+'</div>'}
async function sayWord(hint=true,form='auto'){const cur=view==='study'?E.current(state):null;const word=cur?.word;if(!word)return;
 if(hint&&cur.kind==='spelling'&&cur.phase==='question'){const marked=await questionChange(s=>{if(s.session.current.answered)return false;E.reveal(s,'word-audio')},{renderAfter:false});if(!marked)return;}
 const chosen=form==='auto'?(cur.kind==='dictation'&&cur.phase==='question'&&E.usesGenderPractice(word)?'both':'headword'):form;const spoken=speechText(word,chosen);
 stopAudio();return A.speak(spoken,{rate:state.settings.rate,voiceURI:state.settings.voiceURI,onStatus:audioStatus});}
async function playContext(wordId,contextId,repeat=false){const c=contextAt(wordId,contextId);if(!c)return;const key=wordId+'|'+contextId,generation=++playbackGeneration;loopTarget=repeat?key:null;updateLoopButtons();await A.play(c,{rate:state.settings.rate,voiceURI:state.settings.voiceURI,onStatus:info=>{audioStatus(info);if(info.state==='ended'&&loopTarget===key&&generation===playbackGeneration)setTimeout(()=>{if(loopTarget===key&&generation===playbackGeneration)playContext(wordId,contextId,true)},450)}})}
function updateLoopButtons(){$$('[data-action="loop-context"]').forEach(b=>{const active=loopTarget===b.dataset.word+'|'+b.dataset.context;b.setAttribute('aria-pressed',String(active));b.textContent=active?t('停止循环','Stop loop','Arrêter la boucle'):t('循环播放','Loop','En boucle')})}
