function resetSettingsDraft(){delete themeColourDrafts.classic;delete themeColourDrafts.atelier;delete themeColourDrafts.verdure;settingsDraft={};settingsBaseline=null;pageScroll.clear()}
function settingsValues(form){const values={};for(const key of settingsKeys){const el=form?.elements.namedItem(key);if(!el)continue;values[key]=el.type==='checkbox'?el.checked:key==='dailyGoalEnabled'?el.value==='true':el.value}return values}
function captureSettingsDraft(){const form=$('#settings-form');if(!form||!settingsBaseline)return;const values=settingsValues(form),next={};for(const key of settingsKeys)if(key in values&&String(values[key])!==String(settingsBaseline[key]))next[key]=values[key];settingsDraft=next;updateSettingsSavebar()}
function cleanSettingsStatus(){return PREVIEW?previewNote():storage.persistent?t('设置已保存','Settings saved','Réglages enregistrés'):t('仅在本页临时保留，请导出备份','Temporary changes in this page; export a backup','Modifications temporaires ; exportez une sauvegarde')}
function updateSettingsSavebar(){const bar=$('.settings-savebar');if(!bar)return;const dirty=Object.keys(settingsDraft).length>0;bar.dataset.dirty=String(dirty);bar.querySelector('[data-settings-status]').textContent=dirty?t('有未保存的更改 · 切换页面会保留草稿','Unsaved changes · drafts survive navigation','Modifications non enregistrées · brouillon conservé'):cleanSettingsStatus();bar.querySelector('[type=submit]').disabled=(!dirty&&storage.persistent)||bar.querySelector('[type=submit]').getAttribute('aria-busy')==='true'}
function setMotionPreference(control){captureSettingsDraft();window.VocabMotion?.setMode(control.value);return Promise.resolve(true)}
function syncPlaybackRates(){$$('[data-audio-rate]').forEach(select=>{const value=String(state.settings.rate);if(![...select.options].some(o=>o.value===value)){const option=document.createElement('option');option.value=value;option.textContent=value+'×';select.append(option)}select.value=value})}
async function savePlaybackRate(control){const value=Number(control.value);control.disabled=true;try{const ok=await change(s=>{s.settings.rate=value;return s},{renderAfter:false});syncPlaybackRates();if(ok)toast(t('新速度将在下次播放时生效','New speed applies on the next playback','La nouvelle vitesse sera appliquée à la prochaine lecture'))}finally{if(control.isConnected)control.disabled=false}}
async function saveSettings(form){captureSettingsDraft();const patch={...settingsDraft};if(!Object.keys(patch).length&&storage.persistent)return;const ok=await change(s=>{for(const [key,value]of Object.entries(patch))s.settings[key]=['dailyGoal','newBatch','reviewBatch','rate','retention'].includes(key)?Number(value):value;return s},{renderAfter:false});if(ok){delete themeColourDrafts[designTheme()];if(form.isConnected)captureSettingsDraft();for(const [key,value]of Object.entries(patch))if(String(settingsDraft[key])===String(value))delete settingsDraft[key];settingsBaseline=settingsValues(form);for(const key of Object.keys(settingsDraft))settingsBaseline[key]=state.settings[key];render();(typeof savedToast==='function'?savedToast:toast)(t('设置已保存','Settings saved','Réglages enregistrés'))}}

function theme(){applyDesignStyles();window.VocabMotion?.setMode((view==='settings'?settingsDraft.motionMode:null)||state.settings.motionMode||'standard');let value=state.settings.theme;if(value==='system')value=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.documentElement.dataset.theme=value;document.documentElement.dataset.font=state.settings.font;document.documentElement.dataset.shortcutHints=state.settings.showShortcutHints===false?'hidden':'visible';document.documentElement.lang=state.settings.language==='zh'?'zh-CN':state.settings.language;$('#modal-close').setAttribute('aria-label',t('关闭','Close','Fermer'))}

function designTheme(){const design=state?.settings.designTheme;return ['classic','atelier','verdure'].includes(design)?design:'atelier'}
function applyDesignStyles(){
 const design=designTheme(),root=document.documentElement;root.dataset.designTheme=design;
 $$('[data-design-style]').forEach(sheet=>{const wanted=sheet.dataset.designStyle===design?'all':'not all';if(sheet.media!==wanted)sheet.media=wanted;});
 let dark=state.settings.theme==='dark'||state.settings.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches;
 $('meta[name="theme-color"]').content=design==='verdure'?(dark?'#14231f':'#f5f4ef'):design==='atelier'?(dark?'#101713':'#f5f1e7'):(dark?'#14231f':'#f6f5ef');
 document.title=RELEASE?'不背法语 · '+RELEASE:PREVIEW?'不背法语 · Carnet 预览':CARNET?'不背法语 · CARNET 双主题实验版':design==='atelier'?'L’Atelier · 不背法语 · 双主题实验版':'Vocabulaire · 不背法语 · 双主题实验版';
}
function themeButton(){return '<button type="button" class="text-button theme-switch-button" data-action="theme-picker" aria-label="'+t('切换界面主题','Switch visual theme','Changer de thème')+'"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 4a8 8 0 0 1 0 16z" fill="currentColor" stroke="none"/></svg><span>'+t('主题','Theme','Thème')+'</span></button>'}
function themePicker(){if(CARNET)return '<p class="license-note">'+t('风格、明暗与动效可以分别调整。','Adjust design, colour and motion independently.','Réglez séparément le style, les couleurs et les animations.')+'</p>'+btn(t('调整外观','Appearance','Apparence'),'theme-picker','soft');const selected=designTheme();return '<div class="theme-picker" role="group" aria-label="'+t('选择界面主题','Choose a visual theme','Choisir un thème')+'">'+['classic','atelier','verdure'].map(key=>'<button type="button" class="theme-choice" data-action="select-design" data-design-choice="'+key+'" aria-pressed="'+(selected===key)+'"><span class="theme-preview" aria-hidden="true"><span class="theme-preview-nav"></span><span class="theme-preview-content"><i></i><b></b><em></em></span></span><span class="theme-choice-name">'+(key==='classic'?t('清雅 · CLASSIQUE','Calm · CLASSIQUE','Serein · CLASSIQUE'):key==='verdure'?t('青绿 · VERDURE','Green · VERDURE','Vert · VERDURE'):'ATELIER · '+t('午夜艺术馆','Nocturne','Nocturne'))+'</span><span class="theme-choice-description">'+(key==='classic'?t('熟悉的侧栏，清爽的阅读空间','Familiar sidebar, a calm reading space','Navigation latérale, lecture sereine'):key==='verdure'?t('青绿渐变，柔和自然的阅读空间','Soft green gradients, a natural reading space','Dégradés verts et lecture sereine'):t('艺术排版，金色丝带与沉浸空间','Sculptural gold, an immersive gallery','Or sculptural, galerie immersive'))+'</span><span class="theme-choice-state">'+(selected===key?'✓ '+t('使用中','In use','Actif'):t('切换主题','Use theme','Choisir'))+'</span></button>').join('')+'</div><p class="license-note theme-picker-note">'+t('即点即换，自动保存。所有主题共用词表和学习进度，并分别记住明暗配色。','Switch instantly and save automatically. All themes share your words and progress, and remember their own colour modes.','Changement immédiat et enregistré. Mots et progrès sont partagés ; chaque thème garde ses couleurs.')+'</p>'}
function themeModal(){openModal(t('选择界面主题','Choose a visual theme','Choisir un thème'),themePicker());$('#modal').dataset.themePicker='true'}
async function selectDesignTheme(next){
 if(!['classic','atelier','verdure'].includes(next)||next===designTheme())return;
 if(!await flushDraft())return;captureSettingsDraft();
 const before=designTheme(),themeWasOpen=$('#modal').open&&!!$('#modal-body .theme-picker');
 if('theme' in settingsDraft)themeColourDrafts[before]=settingsDraft.theme;else delete themeColourDrafts[before];
 if(view==='onboarding')readOnboardingDraft();
 const ok=await change(s=>{const current=s.settings.designTheme||'atelier';s.settings.themeByDesign={classic:'light',atelier:'dark',...s.settings.themeByDesign,[current]:s.settings.theme};s.settings.designTheme=next;s.settings.theme=s.settings.themeByDesign[next]||'light';return s},{renderAfter:false});
 if(!ok)return;
 // Avoid recapturing the old form's colour value over the newly selected design.
 settingsBaseline=null;delete settingsDraft.theme;
 if(themeColourDrafts[next]&&themeColourDrafts[next]!==state.settings.theme)settingsDraft.theme=themeColourDrafts[next];
 render();
 if(themeWasOpen){$('#modal-body').innerHTML=themePicker();$('#modal-body').scrollTop=0;}
 const target=(themeWasOpen?$('#modal-body'):$('#app')).querySelector('[data-design-choice="'+next+'"]');target?.focus({preventScroll:true});
 // A gentle fade avoids moving any spelling input or its ancestors.
 if(!window.VocabMotion?.isReduced())window.VocabMotion?.animate($('#app'),[{opacity:.78},{opacity:1}],{duration:260,easing:'ease-out'});
}

