function today(){return todayClassic()}
function onboarding(){if(!onboardingDraft)onboardingDraft=clone(state.settings);return window.VocabWelcome.render({step:onboardingStep,draft:onboardingDraft,replay:onboardingReplay,hasWords:rows().length>0,intent:onboardingIntent,themeButton,t,esc,btn,icon,goTo:welcomeGo})}
function shellClassic(body){const nav=navigation();const page=nav.find(n=>n.id===view)||nav[0];return '<div class="shell"><aside class="sidebar"><div class="brand">不背法语<span>Vocabulaire</span></div><nav>'+nav.map(n=>'<button class="nav-item '+(view===n.id?'active':'')+'" data-action="nav" data-view="'+n.id+'">'+icon(n.icon)+'<span>'+n.label+'</span></button>').join('')+'</nav><div class="sidebar-bottom">'+(PREVIEW?previewNote():t('本地优先 · 无需账户','Local first · No account','Local · Sans compte'))+'<br>'+(PREVIEW?t('示例词表与练习不写入正式存档。','Sample practice stays outside your saved library.','Les exercices restent hors de vos données enregistrées.'):t('定期备份，妥善保存学习进度。','Back up regularly to keep your progress.','Sauvegardez pour garder vos progrès.'))+'<br><button class="text-button" data-action="help">'+t('使用说明与快捷键','Help & shortcuts','Aide et raccourcis')+'</button><br>'+esc(RELEASE||'双主题 · 实验版')+'</div></aside><main class="main"><header class="page-header"><div><h1>'+page.label+'</h1><div class="subtitle">'+t('不背法语 · 每天一点','French, a little every day','Le français, un peu chaque jour')+'</div></div><div class="row"><span class="storage-state">'+(PREVIEW?previewNote():storage.persistent?(RELEASE?t('已在此浏览器保存','Saved in this browser','Enregistré dans ce navigateur'):t('实验存档 · 本地保存','Experimental · saved locally','Expérimental · enregistré')):t('临时使用','Temporary session','Session temporaire'))+'</span>'+themeButton()+'</div></header>'+(!storage.persistent||storage.warning?'<div class="save-banner">'+esc(storage.warning||t('数据未能保存，请导出备份。','Data could not be saved. Export a backup.','Exportez une sauvegarde.'))+'</div>':'')+body+'</main><nav class="mobile-nav" aria-label="'+t('主导航','Main navigation','Navigation principale')+'">'+nav.map(n=>'<button class="'+(view===n.id?'active':'')+'" data-action="nav" data-view="'+n.id+'">'+icon(n.icon)+'<span>'+n.label+'</span></button>').join('')+'</nav></div>'}

function dayKey(n){const d=new Date(n);return [d.getFullYear(),d.getMonth()+1,d.getDate()].join('-')}
function todayEvents(){return E.recentEvents(state,Date.now()-2*864e5).filter(e=>!e.undone&&dayKey(e.time||e.at||0)===dayKey(Date.now()))}
function stats(){const raw=E.stats(state);return raw}
function dueOf(id){const c=state.cards[id];return c?.dueAt||c?.due||c?.card?.due||c?.fsrs?.due||null}
function todayClassic(){const s=stats();const today=todayEvents();const total=scoped().length;const free=state.settings.dailyGoalEnabled===false;const newLeft=free?(s.new||0):Math.min(s.new||0,s.remainingGoal||0);const due=s.due??s.dueCount??0;const learned=s.todayNew??s.learnedToday??0;const reviewed=s.todayReview??s.reviewedToday??0;
 const names=state.decks.filter(d=>state.settings.studyDeckIds.includes(d.id)).map(d=>d.name).join(' + ');
 return '<section class="hero"><div class="eyebrow">BONJOUR.</div><h1>'+t('每天一点，<br>让法语更熟练。','A little every day.<br>More confident in French.','Un peu chaque jour.<br>Plus à l’aise en français.')+'</h1><div class="scope">'+t('当前范围','Study selection','Sélection')+' · '+esc(names||t('尚未选择词表','No decks selected','Aucune liste sélectionnée'))+' <button class="text-button" data-action="scope">'+t('调整','Change','Modifier')+'</button></div></section>'+
 (state.session&&!state.session.done&&E.sessionMatchesScope(state)?'<div class="card resume-card row between wrap"><div><strong>'+t('接着上次的小组继续','Pick up where you left off','Reprendre votre session')+'</strong><div class="muted">'+t('题目、提示与输入都已保留','Your question, hints and input are kept','Votre question, vos indices et votre saisie sont conservés')+'</div></div>'+btn(t('继续学习','Resume','Reprendre')+icon('arrow'),'resume','primary')+'</div>':'')+
 '<div class="today-grid '+(free?'free-rhythm':'')+'"><article class="card task-card"><div class="row between" style="width:100%"><span>'+(free?t('新词 · 随时可学','New · at your own pace','Nouveaux · à votre rythme'):t('新词 · 今日剩余','New · remaining today','Nouveaux · restants'))+'</span>'+icon('book')+'</div><div class="count">'+Math.max(0,newLeft)+'</div>'+btn(free?t('按需学习','Learn at your pace','Apprendre à votre rythme')+icon('arrow'):t('开始学习','Start learning','Apprendre')+icon('arrow'),'start-learn',free?'soft':'primary',!total||!newLeft?'disabled':'')+'</article><article class="card task-card review"><div class="row between" style="width:100%"><span>'+t('到期 · 等待回忆','Due · ready to recall','À revoir · rappel')+'</span>'+icon('repeat')+'</div><div class="count">'+due+'</div>'+btn(t('开始复习','Start review','Réviser')+icon('arrow'),'start-review',free?'primary':'soft',!due?'disabled':'')+'</article></div>'+
 (free?'<p class="rhythm-note">'+(due?t('今天先完成到期复习，新词随时想学就学。','Complete due reviews today; learn new words whenever you like.','Faites les révisions dues ; les nouveaux mots restent à votre rythme.'):t('到期复习已完成。今天学多少新词，由你决定。','All due reviews are done. Choose how many new words to learn.','Les révisions dues sont terminées. Choisissez votre rythme.') )+'</p>':'')+
 (!state.decks.length?'<div class="card empty" style="margin-top:22px"><h2>'+t('让第一张词表住进来','Make room for your first words','Accueillez vos premiers mots')+'</h2><p>'+t('导入自己的词表，也可以从 50 个基础词开始学习。','Import your own list, or start with 50 everyday words.','Importez votre liste, ou commencez avec 50 mots courants.')+'</p><div class="row wrap" style="justify-content:center">'+btn(t('导入词表','Import words','Importer une liste'),'import','primary')+btn(t('恢复备份','Restore backup','Restaurer'),'restore')+btn(t('体验基础词表','Try starter words','Essayer les mots de base'),'seed')+'</div></div>':'')+
 '<div class="today-bottom"><section class="card"><div class="row between"><h3>'+t('每一点努力，都算数','Every little bit counts','Chaque petit pas compte')+'</h3><span class="pill">'+new Date().toLocaleDateString(locale(),{month:'short',day:'numeric'})+'</span></div><div class="stats-row"><div class="stat"><strong>'+learned+'</strong><span>'+t('新学词条','New words','Mots appris')+'</span></div><div class="stat"><strong>'+reviewed+'</strong><span>'+t('正式复习','Reviews','Révisions')+'</span></div><div class="stat"><strong>'+(s.todaySpelling??s.spellingToday??today.filter(e=>e.kind==='spelling'||e.kind==='dictation').length)+'</strong><span>'+t('专项练习','Skill practice','Entraînement')+'</span></div></div>'+weekBars()+'</section><section class="card"><h3>'+t('按自己的需要练习','Practise your way','À votre rythme')+'</h3><p class="muted" style="font-size:12px;margin:11px 0 15px">'+t('每轮首次独立拼对才通过；错词订正后，下一轮再练。','Pass on the first independent try in a round; corrected words return next round.','Validez sans aide du premier coup ; les mots corrigés reviennent au tour suivant.')+'</p><div class="practice-options"><div>'+btn(t('看中文拼写','Spell from meaning','Écrire à partir du sens'),'start-spelling','small',!total?'disabled':'')+'<p>'+t('看中文释义，回忆法语怎么写。','Read the meaning and recall the French spelling.','Lisez le sens et retrouvez l’orthographe française.')+'</p></div><div>'+btn(t('听音听写','Listen and write','Dictée'),'start-dictation','small',!total?'disabled':'')+'<p>'+t('只听法语发音，写出听到的词。','Listen to French and write what you hear.','Écoutez le français et écrivez le mot entendu.')+'</p></div></div><div class="scope-list">'+(free?t('不设每日新词目标','No daily new-word goal','Sans objectif quotidien'):t('每日目标','Daily goal','Objectif quotidien')+' '+state.settings.dailyGoal)+' · '+t('每组新词','New words per group','Mots par groupe')+' '+state.settings.newBatch+'</div></section></div>';
}

function weeklyDetail(day){return '<div class="weekly-selected-date">'+esc(new Date(day.date).toLocaleDateString(locale(),{month:'long',day:'numeric',weekday:'short'}))+'</div><dl class="weekly-counts"><div><dt>'+t('当日新学','New words learned','Nouveaux mots appris')+'</dt><dd><span class="weekly-count-wrap"><strong data-week-count="learned">'+day.learned+'</strong></span>'+t('词','words','mots')+'</dd></div><div><dt>'+t('当日复习','Words reviewed','Mots révisés')+'</dt><dd><span class="weekly-count-wrap"><strong data-week-count="reviewed">'+day.reviewed+'</strong></span>'+t('词','words','mots')+'</dd></div></dl>'}
function weekBars(){
 weeklyDays=E.weeklyActivity(state);if(!weeklyDays.some(d=>d.key===weeklySelectedKey))weeklySelectedKey=weeklyDays[6].key;
 const max=Math.max(1,...weeklyDays.map(d=>d.total)),selected=weeklyDays.find(d=>d.key===weeklySelectedKey);
 return '<section class="weekly-activity" aria-labelledby="weekly-title"><div class="weekly-heading"><h3 id="weekly-title">'+t('最近一周练习情况','Practice this week','Pratique de la semaine')+'</h3><small>'+t('全词库','All decks','Toutes les listes')+'</small></div><div class="weekly-legend" aria-hidden="true"><span><i class="weekly-dot weekly-new"></i>'+t('新学','New words','Apprentissage')+'</span><span><i class="weekly-dot weekly-review"></i>'+t('复习','Review','Révision')+'</span></div><div class="weekly-chart" style="--weekly-selected-index:'+weeklyDays.indexOf(selected)+'" role="group" aria-label="'+t('选择日期查看学习和复习词数','Select a day to see new and reviewed words','Choisir un jour pour voir les mots appris et révisés')+'">'+weeklyDays.map((d,i)=>{
  const stamp=new Date(d.date),label=stamp.toLocaleDateString(locale(),{month:'long',day:'numeric'})+' · '+t('新学','New words','Appris')+' '+d.learned+' · '+t('复习','Review','Révisés')+' '+d.reviewed;
  const segment=(count,kind)=>count?'<i class="weekly-segment weekly-'+kind+'" style="height:'+Math.max(2,100*count/max)+'px"></i>':'';
  return '<button type="button" class="weekly-day" data-action="weekly-day" data-day="'+d.key+'" aria-pressed="'+(d.key===weeklySelectedKey)+'" aria-controls="weekly-details" aria-label="'+esc(label)+'"><span class="weekly-track" aria-hidden="true"><span class="weekly-total">'+d.total+'</span><span class="weekly-stack'+(!d.total?' is-empty':'')+'">'+segment(d.reviewed,'review')+segment(d.learned,'new')+'</span></span><span class="weekly-date" aria-hidden="true">'+(i===6?t('今日','Today',"Auj."):String(stamp.getMonth()+1).padStart(2,'0')+'-'+String(stamp.getDate()).padStart(2,'0'))+'</span></button>'
 }).join('')+'</div><div id="weekly-details" class="weekly-details" data-day="'+selected.key+'" aria-live="polite" aria-atomic="true">'+weeklyDetail(selected)+'</div><p class="weekly-instruction"><span class="weekly-desktop-help">'+t('悬停或点选日期查看','Hover or select a day','Survolez ou choisissez un jour')+'</span><span class="weekly-touch-help">'+t('点选或横滑查看','Tap or swipe to explore','Touchez ou glissez horizontalement')+'</span> · '+t('新学与复习分别按词条计数','Each word counts once per day in each category','Chaque mot compte une fois par jour et par catégorie')+'</p></section>'
}
function weeklyReduced(){return window.VocabMotion?.isReduced?.()??(document.documentElement.dataset.motion==='simple'||matchMedia('(prefers-reduced-motion:reduce)').matches)}
function cancelWeeklyNumbers(details=$('#weekly-details')){
 if(!details)return;details.querySelectorAll('[data-week-count],.weekly-count-previous').forEach(node=>{node.getAnimations?.().forEach(animation=>animation.cancel());if(node.classList.contains('weekly-count-previous'))node.remove()});
}
function updateWeeklyNumber(node,value){
 const previous=node.textContent;node.getAnimations?.().forEach(animation=>animation.cancel());
 node.parentElement.querySelectorAll('.weekly-count-previous').forEach(old=>{old.getAnimations?.().forEach(animation=>animation.cancel());old.remove()});
 node.textContent=String(value);if(previous===String(value)||weeklyReduced()||!node.animate)return;
 const old=document.createElement('span');old.className='weekly-count-previous';old.setAttribute('aria-hidden','true');old.textContent=previous;node.parentElement.append(old);
 const opts={duration:160,easing:'cubic-bezier(.22,.8,.3,1)',fill:'none'};
 node.animate([{transform:'translateY(22%)',opacity:.35},{transform:'none',opacity:1}],opts);
 const departure=old.animate([{transform:'none',opacity:.8},{transform:'translateY(-22%)',opacity:0}],opts);
 departure.finished.then(()=>old.remove(),()=>old.remove());
}
function selectWeeklyDay(button){
 const day=weeklyDays.find(d=>d.key===button?.dataset.day);if(!day||!button.isConnected||!button.closest('.weekly-activity')||$('#modal').open)return;
 weeklySelectedKey=day.key;const chart=button.closest('.weekly-activity'),buttons=[...chart.querySelectorAll('.weekly-day')];
 buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.day===day.key)));
 chart.querySelector('.weekly-chart').style.setProperty('--weekly-selected-index',buttons.indexOf(button));
 const details=chart.querySelector('#weekly-details');if(details.dataset.day!==day.key){
  details.querySelector('.weekly-selected-date').textContent=new Date(day.date).toLocaleDateString(locale(),{month:'long',day:'numeric',weekday:'short'});
  ['learned','reviewed'].forEach(key=>updateWeeklyNumber(details.querySelector('[data-week-count="'+key+'"]'),day[key]));
  details.dataset.day=day.key;
 }
}
function revealWeeklyDetails(chart){
 if(!chart?.isConnected||!matchMedia('(max-width:760px),(hover:none) and (pointer:coarse)').matches)return;
 const details=chart.querySelector('#weekly-details'),nav=$('.mobile-nav'),bottom=Math.min(window.visualViewport?.height||window.innerHeight,nav&&getComputedStyle(nav).display!=='none'?nav.getBoundingClientRect().top:window.innerHeight);
 if(details&&details.getBoundingClientRect().bottom>bottom-12)chart.scrollIntoView({block:'end',behavior:weeklyReduced()?'instant':'smooth'});
}
function nearestWeeklyDay(chart,x){return [...chart.querySelectorAll('.weekly-day')].reduce((best,button)=>{const r=button.getBoundingClientRect(),distance=Math.abs(x-r.left-r.width/2);return !best||distance<best.distance?{button,distance}:best},null)?.button}
function releaseWeeklyGesture(event,cancelled=false){
 const gesture=weeklyGesture;if(!gesture||event&&event.pointerId!==gesture.id)return;
 weeklyGesture=null;
 if(gesture.axis){weeklyClickSuppressedUntil=performance.now()+500;if(gesture.axis==='x'&&!cancelled&&gesture.chart.isConnected){const button=nearestWeeklyDay(gesture.chart,event.clientX);selectWeeklyDay(button);button?.focus({preventScroll:true});revealWeeklyDetails(gesture.chart.closest('.weekly-activity'))}}
 if(gesture.chart.hasPointerCapture?.(gesture.id))gesture.chart.releasePointerCapture(gesture.id);
 gesture.chart.classList.remove('is-scrubbing');
}

function library(){if(selectedDeck&&!state.decks.some(d=>d.id===selectedDeck))selectedDeck='';return '<div class="toolbar" id="library-import-zone"><input type="search" id="word-search" placeholder="'+t('搜索法语、释义或用法','Search words, meanings or usage','Rechercher un mot, un sens…')+'" value="'+esc(search)+'" aria-label="'+t('搜索词库','Search library','Rechercher')+'">'+btn(icon('plus')+t('导入','Import','Importer'),'import','primary')+btn(t('词表管理','Manage decks','Gérer les listes'),'manage')+'</div><div class="library-layout"><aside class="deck-list"><button class="deck-button '+(!selectedDeck?'active':'')+'" data-action="select-deck" data-id="">'+t('全部词条','All words','Tous les mots')+'<small>'+rows().length+'</small></button>'+state.decks.map(d=>'<button class="deck-button '+(selectedDeck===d.id?'active':'')+'" data-action="select-deck" data-id="'+esc(d.id)+'"><span>'+esc(d.name)+'</span><small>'+d.words.length+'</small></button>').join('')+'</aside><div><div class="row between wrap" style="margin-bottom:12px"><select id="word-filter" aria-label="'+t('筛选','Filter','Filtrer')+'">'+[['all',t('所有状态','All states','Tous les états')],['due',t('到期复习','Due for review','À réviser')],['weak',t('最近需巩固','Recent difficulties','Difficultés récentes')],['unconfirmed',t('核对学习项','Check study items','Vérifier les exercices')]].map(([v,l])=>'<option value="'+v+'" '+(filter===v?'selected':'')+'>'+l+'</option>').join('')+'</select>'+btn(t('添加词条','Add word','Ajouter un mot'),'add-word','small',!state.decks.length?'disabled':'')+'</div><div id="library-results">'+wordResults()+'</div></div></div>'}
function recentWeakWords(){
 const latest=new Map(),now=Date.now(),cutoff=now-30*86400000;
 for(const e of (E.recentEvents?.(state)||state.events)){
  const time=Number(e.time||e.at||0);if(e.undone||time<cutoff||time>now||e.correction)continue;
  const skill=e.task==='recall'||['review','relearn','learn-acquired','learn-recall'].includes(e.kind)?'meaning':['spelling','dictation'].includes(e.task||e.kind)?(e.task||e.kind):null;if(!skill)continue;
  const key=e.wordId+'|'+skill,old=latest.get(key);if(!old||time>=old.time)latest.set(key,{wordId:e.wordId,time,weak:e.assisted||e.correct===false||(skill==='meaning'&&Number(e.rating)<=2)});
 }
 return new Set([...latest.values()].filter(e=>e.weak).map(e=>e.wordId));
}
function wordResults(){
 const weak=filter==='weak'?recentWeakWords():null;
 const items=rows().filter(({word:w,deck})=>{if(selectedDeck&&deck.id!==selectedDeck)return false;if(search&&![w.french,w.meaning,w.usage,w.fullMeaning,w.fullUsage].join(' ').toLocaleLowerCase().includes(search.toLocaleLowerCase()))return false;if(filter==='unconfirmed'&&!w.needsConfirmation)return false;if(filter==='due'&&(!dueOf(w.id)||new Date(dueOf(w.id)).getTime()>Date.now()))return false;if(weak&&!weak.has(w.id))return false;return true});
 const pages=Math.max(1,Math.ceil(items.length/100));libraryPage=Math.min(Math.max(0,libraryPage),pages-1);const start=libraryPage*100;
 return '<div class="library-summary" tabindex="-1" role="status">'+items.length+' '+t('个词条','words','mots')+(items.length?' · '+(start+1)+'–'+Math.min(start+100,items.length):'')+'</div>'+(filter==='weak'?'<p class="filter-explanation">'+t('近 30 天内，回忆、拼写或听写的最近一次尝试仍需巩固。该题型独立通过后移出；跟写订正不算独立通过。','The latest recall, spelling or dictation attempt within 30 days still needs practice. An independent pass clears that skill; copying a correction does not.','La dernière tentative de rappel, d’orthographe ou de dictée sous 30 jours reste à renforcer. Une réussite autonome valide cette compétence, contrairement à une correction recopiée.')+'</p>':'')+'<div class="word-list">'+(items.length?items.slice(start,start+100).map(({word:w,deck})=>'<button class="word-row" data-action="word" data-id="'+esc(w.id)+'"><span><span class="fr" lang="fr">'+esc(w.french)+'</span><br><small class="muted">'+esc(w.pos)+' · '+esc(deck.name)+'</small></span><span class="zh">'+esc(w.meaning)+'</span><span class="due">'+(w.needsConfirmation?t('核对学习项','Check study item','Vérifier l’exercice'):dueOf(w.id)?date(dueOf(w.id)):t('未安排','Not scheduled','Non planifié'))+'</span></button>').join(''):'<div class="empty">'+t('没有符合条件的词条','No matching words','Aucun mot correspondant')+'</div>')+'</div>'+(pages>1?'<nav class="library-pagination" aria-label="'+t('词库分页','Library pages','Pages du vocabulaire')+'">'+btn(t('上一页','Previous','Précédent'),'library-page','small','data-page="'+(libraryPage-1)+'" '+(!libraryPage?'disabled':''))+'<span>'+ (libraryPage+1)+' / '+pages+'</span>'+btn(t('下一页','Next','Suivant'),'library-page','small','data-page="'+(libraryPage+1)+'" '+(libraryPage===pages-1?'disabled':''))+'</nav>':'');
}
function refreshLibraryResults(){const results=$('#library-results');if(results)results.innerHTML=wordResults();$$('.deck-button').forEach(b=>{const active=b.dataset.id===selectedDeck;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}

function favoriteButton(word,c,framed=false){const label=c.favorite?t('取消收藏例句','Unsave sentence','Retirer des favoris'):t('收藏例句','Save sentence',"Enregistrer l’exemple");return '<button type="button" class="icon-button favorite-button '+(framed?'framed':'')+'" data-action="favorite" data-word="'+esc(word.id)+'" data-context="'+esc(c.id)+'" aria-label="'+label+'" aria-pressed="'+Boolean(c.favorite)+'"><span aria-hidden="true">'+(c.favorite?'♥':'♡')+'</span></button>'}
function dictionaryDetails(w){const d=w.importedDictionary;if(!d)return '';return '<details class="dictionary-details"><summary>'+t('法语助手 · 原始解释与笔记','French Assistant · original entry & notes','French Assistant · entrée et notes originales')+'</summary><p class="dictionary-note">'+t('以下是未整理的导出原文，供核对来源。用于学习的内容可先交给 AI 整理，再导入更新。','Unprocessed source text for reference. Prepare learning content with AI, then import the result.','Texte brut à titre de référence. Préparez le contenu avec l’IA, puis importez le résultat.')+'</p><div class="dictionary-meta">'+(d.stars?t('原星标','Original rating','Évaluation d’origine')+' '+esc(d.stars):'')+(d.ordinal?' · '+t('原序号','Original number','Numéro d’origine')+' '+esc(d.ordinal):'')+'</div><div class="dictionary-original">'+esc(d.definition)+'</div>'+(d.notes?'<h3>'+t('原笔记','Original notes','Notes originales')+'</h3><div class="dictionary-original">'+esc(d.notes)+'</div>':'')+'</details>'}
function contextCard(word,c,compact=false){return '<article class="context-card" data-context-key="'+esc(word.id+'|'+c.id)+'"><div class="source-line"><span class="badge">'+mediaLabel(c)+'</span>'+sourceLink(c)+'</div><div class="sentence" lang="fr">'+highlight(c.text,word,c.target)+'</div><p class="translation">'+esc(c.translation)+'</p>'+(c.author||c.license?'<p class="license-note" style="margin-top:14px">'+esc(c.author)+(c.author&&c.license?' · ':'')+(c.licenseUrl&&/^https:\/\//i.test(c.licenseUrl)?'<a href="'+esc(c.licenseUrl)+'" target="_blank" rel="noopener noreferrer">'+esc(c.license)+'</a>':esc(c.license))+'</p>':'')+'<footer><div class="row wrap">'+btn(icon('audio'),'play-context','small','data-word="'+esc(word.id)+'" data-context="'+esc(c.id)+'" aria-label="'+t('播放例句','Play sentence',"Écouter l’exemple")+'"')+favoriteButton(word,c,true)+(!compact?btn(icon('edit'),'edit-context','small','data-word="'+esc(word.id)+'" data-context="'+esc(c.id)+'" aria-label="'+t('编辑例句','Edit example',"Modifier l’exemple")+'"'):'')+'</div><button class="text-button" data-action="word" data-id="'+esc(word.id)+'" lang="fr">'+esc(word.french)+'</button></footer><div class="row wrap" style="margin-top:12px">'+btn(t('循环播放','Loop','En boucle'),'loop-context','small','data-word="'+esc(word.id)+'" data-context="'+esc(c.id)+'" aria-pressed="false"')+'<label class="source-line">'+t('速度','Speed','Vitesse')+' <select data-audio-rate aria-label="'+t('朗读速度','Playback speed','Vitesse de lecture')+'">'+[.75,1,1.25].map(v=>'<option value="'+v+'" '+(state.settings.rate===v?'selected':'')+'>'+v+'×</option>').join('')+(![.75,1,1.25].includes(state.settings.rate)?'<option value="'+state.settings.rate+'" selected>'+state.settings.rate+'×</option>':'')+'</select></label></div></article>'}
function matchingContexts(){const query=contextSearch.trim().normalize('NFD').replace(/\p{M}/gu,'').toLocaleLowerCase();if(contextDeck&&!state.decks.some(d=>d.id===contextDeck))contextDeck='';return rows().flatMap(({word,deck})=>contexts(word).map(c=>({word,c,deck,key:word.id+'|'+c.id}))).filter(({word,c,deck})=>(!contextOnlyFavorites||c.favorite)&&(!contextDeck||deck.id===contextDeck)&&(!query||[word.french,word.meaning,c.text,c.translation,c.source].join(' ').normalize('NFD').replace(/\p{M}/gu,'').toLocaleLowerCase().includes(query)))}
function contextDeckOptions(){return '<option value="">'+t('全部词表','All decks','Toutes les listes')+'</option>'+state.decks.map(d=>'<option value="'+esc(d.id)+'" '+(d.id===contextDeck?'selected':'')+'>'+esc(d.name)+'</option>').join('')}
function contextPage(){const chosen=matchingContexts();return '<section class="context-view"><div class="toolbar context-toolbar"><div class="context-segmented" role="group" aria-label="'+t('例句筛选','Filter examples','Filtrer les exemples')+'" data-selection="'+(contextOnlyFavorites?'saved':'all')+'"><button type="button" class="context-filter" data-action="context-filter" data-favorite="true" aria-pressed="'+contextOnlyFavorites+'">'+t('我的收藏','Saved examples','Mes favoris')+'</button><button type="button" class="context-filter" data-action="context-filter" data-favorite="false" aria-pressed="'+!contextOnlyFavorites+'">'+t('所有例句','All examples','Tous les exemples')+'</button></div><span class="muted context-count" aria-live="polite">'+chosen.length+'</span></div><div class="context-search-tools"><input type="search" id="context-search" value="'+esc(contextSearch)+'" placeholder="'+t('搜索单词、例句或译文','Search words, examples or translations','Rechercher des mots, exemples ou traductions')+'" aria-label="'+t('搜索例句库','Search examples','Rechercher les exemples')+'"><select id="context-deck" aria-label="'+t('按词表筛选例句','Filter examples by deck','Filtrer les exemples par liste')+'">'+contextDeckOptions()+'</select></div><div class="context-grid" '+(!chosen.length?'hidden':'')+'>'+chosen.slice(0,contextLimit).map(({word,c})=>contextItem(word,c)).join('')+'</div><div class="card empty context-empty" '+(chosen.length?'hidden':'')+'>'+contextEmpty()+'</div><div class="context-paging"><span class="context-page-status" role="status">'+Math.min(contextLimit,chosen.length)+' / '+chosen.length+'</span>'+btn(t('加载更多例句','Load more examples','Afficher plus d’exemples'),'context-more','soft context-load-more',contextLimit>=chosen.length?'hidden':'')+'</div></section>'}

function contextItem(word,c){return '<div class="context-item" data-context-key="'+esc(word.id+'|'+c.id)+'">'+contextCard(word,c)+'</div>'}
function contextEmpty(){if(contextSearch||contextDeck)return '<h2>'+t('没有匹配的例句','No matching examples','Aucun exemple correspondant')+'</h2><p>'+t('试试其他关键词，或清除词表与搜索条件。','Try another keyword, or clear the deck and search filters.','Essayez un autre mot ou effacez les filtres.')+'</p>'+btn(t('清除筛选','Clear filters','Effacer les filtres'),'context-reset','soft');return '<h2>'+t('留住有感觉的表达','Keep the expressions you love','Gardez les expressions qui vous parlent')+'</h2><p>'+t('学习时点一下爱心，就能在这里再次听到和读到它。','Tap the heart while learning to read and hear an example again here.','Touchez le cœur pendant votre apprentissage pour retrouver cet exemple ici.')+'</p>'+btn(t('浏览全部例句','Browse examples','Parcourir les exemples'),'all-contexts','soft')}
const contextAnimations=new Set(),favoritePending=new Set();
const contextReduced=()=>window.VocabMotion?.isReduced?.()??matchMedia('(prefers-reduced-motion:reduce)').matches;
function contextAnimate(element,frames,options){if(!element?.animate||contextReduced()||document.hidden)return null;const animation=element.animate(frames,options);contextAnimations.add(animation);animation.finished.catch(()=>{}).finally(()=>contextAnimations.delete(animation));return animation}
function contextFingerprint(word,c){const content={...c};delete content.favorite;return JSON.stringify([state.settings.language,word.french,word.spell,word.masc,content])}
function setupContextView(){const root=$('.context-view');if(!root)return;if(!root._contextNodes){root._contextNodes=new Map([...root.querySelectorAll('.context-item')].map(node=>[node.dataset.contextKey,node]));for(const {word}of rows())for(const c of contexts(word)){const node=root._contextNodes.get(word.id+'|'+c.id);if(node)node._contextFingerprint=contextFingerprint(word,c)}root._contextLanguage=state.settings.language;root._contextGeneration=0}return root}
function syncFavoriteButtons(wordId,contextId){const c=contextAt(wordId,contextId);if(!c)return;$$('[data-action="favorite"]').filter(b=>b.dataset.word===wordId&&b.dataset.context===contextId).forEach(button=>{button.setAttribute('aria-pressed',String(Boolean(c.favorite)));button.setAttribute('aria-label',c.favorite?t('取消收藏例句','Unsave sentence','Retirer des favoris'):t('收藏例句','Save sentence','Enregistrer l’exemple'));const glyph=button.querySelector('span');if(glyph)glyph.textContent=c.favorite?'♥':'♡';button.disabled=favoritePending.has(wordId+'|'+contextId);if(button.disabled)button.setAttribute('aria-busy','true');else button.removeAttribute('aria-busy')})}
function favoriteFeedback(wordId,contextId,saved){if(contextReduced()||document.hidden)return;$$('[data-action="favorite"]').filter(b=>b.dataset.word===wordId&&b.dataset.context===contextId&&!b.closest('[hidden]')&&b.getClientRects().length).forEach(button=>{const glyph=button.querySelector('span');if(glyph)contextAnimate(glyph,[{transform:'scale(1)'},{transform:'scale(.96)',offset:.18},{transform:'scale(1.01)',offset:.68},{transform:'scale(1)'}],{duration:saved?270:150,easing:'cubic-bezier(.22,.8,.25,1)'});button.querySelector('.favorite-burst')?.remove();if(!saved)return;const burst=document.createElement('span');burst.className='favorite-burst';burst.setAttribute('aria-hidden','true');for(let i=0;i<5;i++){const dot=document.createElement('i'),angle=(-110+i*72)*Math.PI/180;burst.appendChild(dot);const motion=contextAnimate(dot,[{transform:'translate(0,0) scale(.45)',opacity:0},{opacity:.7,offset:.18},{transform:'translate('+Math.cos(angle)*21+'px,'+Math.sin(angle)*21+'px) scale(.5)',opacity:0}],{duration:360,easing:'cubic-bezier(.2,.7,.3,1)',fill:'both'});motion?.finished.catch(()=>{}).finally(()=>{if(i===4)burst.remove()})}button.appendChild(burst)})}
async function updateContextView({animate=true}={}){
 const root=setupContextView();if(!root)return;const generation=++root._contextGeneration,grid=root.querySelector('.context-grid'),cache=root._contextNodes;
 const all=rows().flatMap(({word})=>contexts(word).map(c=>({word,c,key:word.id+'|'+c.id}))),chosen=matchingContexts(),visible=chosen.slice(0,contextLimit),wanted=new Set(visible.map(x=>x.key)),known=new Set(all.map(x=>x.key));
 const selected=root.querySelector('.context-segmented');selected.dataset.selection=contextOnlyFavorites?'saved':'all';selected.setAttribute('aria-label',t('例句筛选','Filter examples','Filtrer les exemples'));
 const filters=[...selected.querySelectorAll('[data-action="context-filter"]')];filters.forEach(button=>{const saved=button.dataset.favorite==='true';button.setAttribute('aria-pressed',String(saved===contextOnlyFavorites));button.textContent=saved?t('我的收藏','Saved examples','Mes favoris'):t('所有例句','All examples','Tous les exemples')});root.querySelector('.context-count').textContent=chosen.length;root.querySelector('.context-page-status').textContent=Math.min(contextLimit,chosen.length)+' / '+chosen.length;root.querySelector('[data-action="context-more"]').hidden=contextLimit>=chosen.length;const deckSelect=root.querySelector('#context-deck');if(deckSelect){const options=contextDeckOptions();if(deckSelect.innerHTML!==options)deckSelect.innerHTML=options;deckSelect.value=contextDeck}
 const active=document.activeElement,oldVisible=[...grid.children].filter(node=>!node.hidden),activeItem=active?.closest('.context-item'),removingFocus=activeItem&&grid.contains(activeItem)&&!wanted.has(activeItem.dataset.contextKey),focusIndex=oldVisible.indexOf(activeItem);
 // Read visual positions before cancelling an interrupted reflow. Tilt remains on the inner card.
 const before=new Map(oldVisible.map(node=>[node,node.getBoundingClientRect()]));oldVisible.forEach(node=>node.getAnimations().forEach(animation=>animation.cancel()));
 const leaving=oldVisible.filter(node=>!wanted.has(node.dataset.contextKey));
 if(animate&&!contextReduced()&&!document.hidden&&leaving.length){const fades=leaving.map(node=>contextAnimate(node,[{opacity:1},{opacity:0}],{duration:140,easing:'ease-out',fill:'forwards'}));await Promise.all(fades.filter(Boolean).map(animation=>animation.finished.catch(()=>{})));if(!root.isConnected||generation!==root._contextGeneration)return}
 if(!root.isConnected||generation!==root._contextGeneration)return;
 const languageChanged=root._contextLanguage!==state.settings.language;
 for(const [key,node]of cache){node.getAnimations().forEach(animation=>animation.cancel());if(!known.has(key)){node.remove();cache.delete(key)}else node.hidden=!wanted.has(key)}
 for(const {word,c,key}of visible){let node=cache.get(key);if(!node){const template=document.createElement('template');template.innerHTML=contextItem(word,c);node=template.content.firstElementChild;cache.set(key,node);grid.appendChild(node)}else if(node._contextFingerprint!==contextFingerprint(word,c)){node.innerHTML=contextCard(word,c)}node._contextFingerprint=contextFingerprint(word,c);node.hidden=false;syncFavoriteButtons(word.id,c.id)}
 // Reorder only when necessary: appending a connected focused card would needlessly blur it.
 let previous=null;for(const {key}of visible){const node=cache.get(key),candidate=previous?previous.nextElementSibling:grid.firstElementChild;if(candidate!==node)grid.insertBefore(node,candidate);previous=node}
 root._contextLanguage=state.settings.language;const empty=root.querySelector('.context-empty');if(languageChanged||!chosen.length)empty.innerHTML=contextEmpty();empty.hidden=Boolean(chosen.length);grid.hidden=!chosen.length;
 if(animate&&!contextReduced()&&!document.hidden){for(const {key}of visible){const node=cache.get(key),old=before.get(node),after=node.getBoundingClientRect();if(old){const dx=old.left-after.left,dy=old.top-after.top;if(Math.abs(dx)+Math.abs(dy)>1)contextAnimate(node,[{transform:'translate('+dx+'px,'+dy+'px)'},{transform:'translate(0,0)'}],{duration:220,easing:'cubic-bezier(.2,.8,.2,1)'})}else contextAnimate(node,[{opacity:.2},{opacity:1}],{duration:150,easing:'ease-out'})}}
 if(removingFocus&&(document.activeElement===active||document.activeElement===document.body)){const next=visible[Math.min(Math.max(0,focusIndex),visible.length-1)],target=next?cache.get(next.key)?.querySelector('[data-action="favorite"]'):filters.find(button=>button.getAttribute('aria-pressed')==='true');target?.focus({preventScroll:true})}
 updateLoopButtons();syncPlaybackRates();
}
function filterContexts(saved){contextOnlyFavorites=saved;contextLimit=100;return updateContextView()}
window.addEventListener('vocab-motionchange',()=>{for(const animation of contextAnimations)animation.cancel();$$('.favorite-burst').forEach(node=>node.remove());if(view==='contexts')updateContextView({animate:false})});
document.addEventListener('visibilitychange',()=>{if(document.hidden){for(const animation of contextAnimations)animation.cancel();$$('.favorite-burst').forEach(node=>node.remove());if(view==='contexts')updateContextView({animate:false})}});
function field(label,name,value,type='text',extra=''){return '<div class="field"><label for="'+name+'">'+label+'</label><input id="'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></div>'}
function selectField(label,id,options,value){return '<div class="field"><label for="'+id+'">'+label+'</label><select id="'+id+'" name="'+id+'">'+options.map(([v,l])=>'<option value="'+esc(v)+'" '+(String(value)===String(v)?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select></div>'}
function settings(){settingsBaseline={...state.settings};const s={...state.settings,...settingsDraft};return '<section class="card theme-settings-card"><h3>'+t('界面主题','Visual theme','Thème visuel')+'</h3>'+themePicker()+'</section><form id="settings-form"><div class="settings-grid"><section class="card settings-card"><h3>'+t('学习节奏','Learning rhythm',"Rythme d’apprentissage")+'</h3>'+selectField(t('学习方式','Learning pace','Rythme'),'dailyGoalEnabled',[['true',t('每日新词目标','Daily new-word goal','Objectif quotidien')],['false',t('自由学习 · 不设目标','Free pace · no goal','À mon rythme · sans objectif')]],String(s.dailyGoalEnabled!==false))+'<p class="license-note" style="margin-bottom:18px">'+t('自由学习时每天只需完成到期复习；新词按需学习，每组数量保持不变。','At your own pace, only due reviews are daily tasks. New words stay optional, in the same short groups.','Sans objectif, seules les révisions dues sont quotidiennes. Les nouveaux mots restent facultatifs, par petits groupes.')+'</p><div class="field two"><div id="daily-goal-field" '+(s.dailyGoalEnabled===false?'hidden':'')+'>'+field(t('每日新词目标','Daily new words','Nouveaux mots par jour'),'dailyGoal',s.dailyGoal,'number','required min="1" max="200" '+(s.dailyGoalEnabled===false?'disabled':''))+'</div>'+field(t('每组新词','New words per group','Nouveaux mots par groupe'),'newBatch',s.newBatch,'number','required min="1" max="100"')+'</div>'+field(t('每组复习','Reviews per group','Révisions par groupe'),'reviewBatch',s.reviewBatch,'number','required min="1" max="100"')+selectField(t('目标保持率','Target retention','Rétention souhaitée'),'retention',[[.8,'80%'],[.85,'85%'],[.9,'90%'],[.95,'95%']],s.retention)+'<p class="license-note">'+t('保持率是调度目标。设得更高通常需要更多复习，不代表实际记忆效果保证。','Retention is a scheduling target. Higher targets usually mean more reviews, not a guarantee.','Un objectif plus élevé implique généralement davantage de révisions, sans garantie de résultat.')+'</p><div class="divider"></div>'+btn(t('选择学习词表','Choose study decks','Choisir les listes'),'scope')+'</section><section class="card settings-card"><h3>'+t('学习偏好','Learning preferences','Préférences d’apprentissage')+'</h3><label class="check-row"><input name="listening" type="checkbox" '+(s.listening?'checked':'')+'><span>'+t('开启听音选择题','Use listening multiple-choice questions','Activer les choix à l’écoute')+'</span></label><p class="license-note">'+t('开启后，新词辨识阶段听法语、选释义；关闭后看法语、选释义。之后仍会练习独立回忆。保存后从新一组生效。','When enabled, listen to French and choose the meaning; otherwise read the word. Independent recall follows in both cases. Applies to new groups.','Écoutez le français et choisissez le sens, ou lisez le mot si cette option est désactivée. Le rappel suit dans les deux cas. Dès le prochain groupe.')+'</p><div class="divider"></div><h3>'+t('阅读与界面','Reading & interface','Lecture et interface')+'</h3>'+selectField(t('界面语言','Interface language',"Langue de l’interface"),'language',[['zh','简体中文'],['en','English'],['fr','Français']],s.language)+(CARNET?'':selectField(t('当前主题的明暗配色','Colour mode for this theme','Couleurs de ce thème'),'theme',[['system',t('跟随系统','System','Système')],['light',t('明亮','Light','Clair')],['dark',t('深色','Dark','Sombre')]],s.theme)+selectField(t('界面动效','Interface motion','Animations'),'motionMode',[['standard',t('标准 · 自然流畅','Standard · fluid','Standard · fluide')],['simple',t('简约 · 安静直接','Simple · calm','Simple · sobre')]],s.motionMode||'standard')+'<p class="license-note motion-preference-note">'+t('选择动效可预览；本页设置统一点击“保存设置”后保留。系统的“减少动态效果”始终优先。','Preview motion here; use Save settings to keep changes on this page. System reduced motion always takes priority.','Prévisualisez les animations ; cliquez sur Enregistrer pour conserver les réglages. La réduction des animations du système reste prioritaire.')+'</p>')+selectField(t('法语词头字体','French word font','Police des mots français'),'font',[['serif',t('衬线 · 优雅','Serif','Avec empattements')],['sans',t('无衬线 · 清晰','Sans serif','Sans empattements')]],s.font)+'<label class="check-row desktop-shortcut-setting"><input name="showShortcutHints" type="checkbox" '+(s.showShortcutHints!==false?'checked':'')+'><span>'+t('显示快捷键提示（电脑端）','Show keyboard hints (desktop)','Afficher les raccourcis (ordinateur)')+'</span></label>'+'<p class="license-note">'+t('界面语言不会改写词表中的中文释义或例句译文。','Interface language does not rewrite the translations in your word lists.','La langue de l’interface ne modifie pas les traductions de vos listes.')+'</p></section><section class="card settings-card"><h3>'+t('声音','Sound','Son')+'</h3><label class="check-row"><input name="autoWord" type="checkbox" '+(s.autoWord?'checked':'')+'><span>'+t('在安全的题面自动读单词','Auto-play words when it will not reveal the answer','Lire les mots sans révéler la réponse')+'</span></label><label class="check-row"><input name="autoExample" type="checkbox" '+(s.autoExample?'checked':'')+'><span>'+t('揭晓后自动读首条例句','Auto-play the first example after reveal',"Lire le premier exemple après révélation")+'</span></label>'+field(t('播放速度（0.5–1.5）','Playback speed (0.5–1.5)','Vitesse (0,5–1,5)'),'rate',s.rate,'number','required min="0.5" max="1.5" step="0.01"')+selectField(t('合成朗读声音','Synthetic voice','Voix de synthèse'),'voiceURI',voiceOptions(s.voiceURI),s.voiceURI)+'<p class="license-note">'+t('默认优先使用 Google français；浏览器没有提供时，自动使用其他法语声音。真人录音按来源播放，离线合成语音取决于设备支持。','Google français is preferred by default, with another French voice as fallback. Recordings retain their source; offline synthesis depends on your device.','Google français est privilégié, avec une autre voix française en secours. Les enregistrements gardent leur source ; la synthèse hors ligne dépend de votre appareil.')+'</p></section>'+backupSection()+'</div><div class="settings-savebar"><span class="license-note" data-settings-status role="status">'+(Object.keys(settingsDraft).length?t('有未保存的更改 · 切换页面会保留草稿','Unsaved changes · drafts survive navigation','Modifications non enregistrées · brouillon conservé'):cleanSettingsStatus())+'</span><button type="submit" class="button primary" '+(!Object.keys(settingsDraft).length&&storage.persistent?'disabled':'')+'>'+t('保存设置','Save settings','Enregistrer')+'</button></div></form>'+aboutSection()}
function backupSection(){return '<section class="card settings-card" id="backup-section"><h3>'+t('数据与备份','Data & backup','Données et sauvegardes')+'</h3><p class="license-note">'+t('备份包含词表、学习进度和已导入的音频。换设备时，恢复这一个文件即可。','One backup includes your words, progress and imported audio. Restore it to move to another device.','Un fichier contient vos mots, progrès et audios importés. Restaurez-le sur un autre appareil.')+'</p><div class="backup-actions">'+btn(t('备份到文件','Save backup file','Créer une sauvegarde'),'backup-full','primary')+btn(t('从备份恢复','Restore from file','Restaurer un fichier'),'restore')+'</div><p class="license-note">'+(PREVIEW?t('此验收入口仅保留本次会话的数据。若要保留试用结果，请先导出备份；正式存档不会被读取。','This review keeps data only for this session. Export a backup to keep your trial; saved user records are never read.','Cet aperçu conserve les données pour cette session. Exportez-les pour garder vos essais ; vos données personnelles ne sont jamais lues.') : t('数据保存在此浏览器中；更名、换浏览器或设备前请备份。','Data stays in this browser. Back up before renaming the file or changing browsers or devices.','Les données restent dans ce navigateur. Sauvegardez avant de changer de fichier, de navigateur ou d’appareil.'))+'</p><details class="data-tools"><summary>'+t('更多数据工具','More data tools','Autres outils')+'</summary><div class="data-tool-list">'+btn(t('管理本地音频','Manage local audio','Gérer les audios locaux'),'media-manage','small')+btn(t('回收站','Trash','Corbeille'),'trash','small')+btn(t('恢复先前保存的快照','Restore a previous snapshot','Restaurer un état antérieur'),'snapshots','small')+btn(t('导出便携 HTML','Export portable HTML','Exporter un HTML portable'),'portable','small')+btn(t('仅备份词表与进度（不含音频）','Backup without audio','Sauvegarde sans audio'),'backup','small')+(RELEASE?btn(t('清除本机学习数据','Clear local learning data','Effacer les données locales'),'reset-local','small danger'):'')+(state.migration?.original?btn(t('导出原始备份','Export original backup','Exporter la sauvegarde originale'),'backup-legacy','small'):'')+'</div><p class="license-note">'+(PREVIEW?t('快照用于撤回本次试用操作。便携 HTML 携带当前数据与音频，重新打开时恢复这份快照；之后的练习仅保留在内存中，需要再次导出才能带走。','Snapshots undo trial changes. Portable HTML restores its embedded data and audio on opening. Later practice stays in memory; export again to keep it.','Les instantanés annulent les essais. Le HTML portable restaure ses données et audios intégrés. Les nouveaux progrès restent en mémoire ; exportez de nouveau pour les conserver.') : t('快照用于撤回重置等操作。便携 HTML 可携带当前数据直接打开，之后的学习仍保存在浏览器中。','Snapshots help undo operations such as resets. Portable HTML opens with a copy of your data; later progress stays in the browser.','Les instantanés permettent de revenir avant une remise à zéro. Le HTML portable contient vos données ; les progrès ultérieurs restent dans le navigateur.'))+'</p></details></section>'}
function readOnboardingDraft(){
 const form=$('#onboarding-form');if(!form)return;
 if(!onboardingDraft)onboardingDraft=clone(state.settings);
 for(const key of onboardingKeys){const control=form.elements.namedItem(key);if(!control||control.disabled)continue;
  if(['listening','autoWord','autoExample'].includes(key))onboardingDraft[key]=control.checked;
  else if(key==='dailyGoalEnabled')onboardingDraft[key]=control.value==='true';
  else if(['dailyGoal','newBatch'].includes(key))onboardingDraft[key]=control.value.trim()===''?'':Number(control.value);
  else onboardingDraft[key]=control.value;
 }
}
function welcomeGo(index){
 if(view!=='onboarding'||onboardingCompleting)return false;
 const count=window.VocabWelcome.COUNT,target=Math.max(0,Math.min(count-1,Number(index)));
 if(!Number.isInteger(target))return false;
 readOnboardingDraft();
 if(target>onboardingStep&&onboardingStep===4&&$('#onboarding-form')&&!$('#onboarding-form').reportValidity())return false;
 if(target===onboardingStep)return true;
 stopAudio();onboardingStep=target;render();return true;
}
function resetOnboarding(replay=false){
 window.VocabWelcome?.reset();onboardingStep=0;onboardingDraft=clone(state.settings);onboardingReplay=replay;onboardingIntent=rows().length?'home':'seed';
}
function clearOnboarding(){window.VocabWelcome?.reset();onboardingDraft=null;onboardingStep=0;onboardingReplay=false;onboardingIntent='home';}
async function replayOnboarding(){
 if(CARNET){if(!await flushDraft())return false;captureSettingsDraft();stopAudio();document.dispatchEvent(new CustomEvent('carnet:open-story',{detail:{replay:true}}));return true;}
 if(onboardingCompleting)return;const navigation=++navigationRevision;
 if(await flushDraft()===false||navigation!==navigationRevision)return;
 captureSettingsDraft();stopAudio();resetOnboarding(true);view='onboarding';render();
}
async function completeOnboarding(){
 if(view!=='onboarding'||onboardingCompleting)return false;
 readOnboardingDraft();const preferences={};for(const key of onboardingKeys)preferences[key]=onboardingDraft[key];
 preferences.dailyGoal=Number(preferences.dailyGoal);preferences.newBatch=Number(preferences.newBatch);
 if(preferences.dailyGoalEnabled===false&&(!Number.isInteger(preferences.dailyGoal)||preferences.dailyGoal<1||preferences.dailyGoal>200))preferences.dailyGoal=state.settings.dailyGoal;
 if(!Number.isInteger(preferences.dailyGoal)||preferences.dailyGoal<1||preferences.dailyGoal>200||!Number.isInteger(preferences.newBatch)||preferences.newBatch<1||preferences.newBatch>100){onboardingStep=4;render();$('#onboarding-form')?.reportValidity();return false;}
 const intent=onboardingIntent;onboardingCompleting=true;stopAudio();
 try{const ok=await change(s=>{for(const key of onboardingKeys)s.settings[key]=preferences[key];s.settings.onboardingComplete=true;return s},{renderAfter:false});
  if(!ok)return false;
  for(const key of onboardingKeys)delete settingsDraft[key];
  clearOnboarding();view='today';render();window.scrollTo(0,0);
  if(intent==='seed')await seed();else if(intent==='import')importModal();
  return true;
 }finally{onboardingCompleting=false;}
}
async function exitOnboarding(){
 if(view!=='onboarding'||onboardingCompleting)return false;
 const replay=onboardingReplay;onboardingCompleting=true;stopAudio();
 try{if(!replay&&!await change(s=>{s.settings.onboardingComplete=true;return s},{renderAfter:false}))return false;
  clearOnboarding();view=replay?'settings':'today';render();window.scrollTo(0,0);return true;
 }finally{onboardingCompleting=false;}
}

function voiceOptions(selected=''){
 const voices=[...new Map((window.speechSynthesis?.getVoices()||[]).filter(v=>v.voiceURI).map(v=>[v.voiceURI,v])).values()],french=v=>/^fr(?:[-_]|$)/i.test(v.lang),automatic=A.selectVoice?.(voices,''),name=v=>v.name+(v.lang?' · '+v.lang:'');
 const options=[['',automatic?t('自动 · ','Automatic · ','Automatique · ')+name(automatic):t('自动 · Google français 优先','Automatic · Google français preferred','Automatique · Google français en priorité')],...voices.sort((a,b)=>Number(french(b))-Number(french(a))||String(a.lang).localeCompare(String(b.lang))||a.name.localeCompare(b.name)).map(v=>[v.voiceURI,name(v)])];
 if(selected&&!options.some(([v])=>v===selected))options.push([selected,selected+' · '+t('暂不可用','Currently unavailable','Indisponible')]);return options;
}
function refreshVoices(){const select=$('#settings-form [name="voiceURI"]');if(!select)return;const selected=select.value;select.innerHTML=voiceOptions(selected).map(([v,label])=>'<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(label)+'</option>').join('')}
window.speechSynthesis?.addEventListener?.('voiceschanged',refreshVoices);
