function fullDefinitionButton(w){return '<button type="button" class="text-button full-definition-link" data-action="full-word" data-id="'+esc(w.id)+'">'+t('查看完整释义及用法','Full meanings & usage','Sens et usages complets')+'</button>'}
function hasFullEntry(w){return !!(w.fullMeaning||w.fullUsage||w.originalMeaning||w.originalNotes||w.importedDictionary)}
function fullWordContent(w){
 const rawMeaning=w.originalMeaning!==undefined?w.originalMeaning:w.importedDictionary?.definition||'',rawNotes=w.originalNotes!==undefined?w.originalNotes:w.importedDictionary?.notes||'';
 const meaning=w.fullMeaning||rawMeaning||w.meaning,usage=w.fullUsage||w.usage;
 const section=(title,text)=>text?'<section class="full-entry-section"><h3>'+title+'</h3><div class="full-entry-text">'+esc(text)+'</div></section>':'';
 const source=w.fullMeaning&&rawMeaning?rawMeaning:'';
 return '<article class="full-entry"><header class="full-entry-heading"><div class="headword" lang="fr">'+esc(w.french)+'</div><div class="muted">'+esc([w.phonetic,w.pos].filter(Boolean).join(' · '))+'</div></header>'
  +section(w.fullMeaning?t('完整释义','Full meanings','Sens complets'):rawMeaning?t('原始完整释义','Full source definition','Définition source complète'):t('现有释义','Available meaning','Sens disponible'),meaning)
  +section(t('完整用法与搭配','Usage & collocations','Usages et expressions'),usage)
  +(!hasFullEntry(w)?'<p class="full-entry-note">'+t('此词条暂未附带更多完整内容。可使用整理提示词补全原文件，再选择“合并并更新现有词表”，保留学习进度。','This entry has no additional full content yet. Prepare the source with the import prompt, then merge into the existing deck to keep progress.','Ce mot ne contient pas encore de détails supplémentaires. Utilisez les consignes d’import puis fusionnez avec la liste existante pour conserver les progrès.')+'</p>':'')
  +(source||rawNotes?'<details class="full-entry-source"><summary>'+t('核对原始资料','Check original source','Vérifier le texte source')+'</summary>'+section(t('原始释义','Original definition','Définition originale'),source)+section(t('原始笔记','Original notes','Notes originales'),rawNotes)+'</details>':'')+'</article>';
}
function fullWordModal(id,origin=null){const found=findWord(id);if(!found)return;if(view==='study'&&!E.current(state)?.revealed&&!E.current(state)?.answered)return;stopAudio();openModal(t('完整释义及用法','Full meanings & usage','Sens et usages complets'),fullWordContent(found.word),btn(t('词条与例句','Word & examples','Mot et exemples'),'word','','data-id="'+esc(id)+'"')+btn(t('完成','Done','Terminé'),'close','primary'),false,origin?{origin,shared:true}:null)}
