function restoreImportView(){if(!importReturn)return;openModal(t('导入词表','Import words','Importer une liste'),importReturn.body,importReturn.footer);$('#import-name').value=importReturn.name;$('#import-mode').value=importReturn.mode;$('#import-target').value=importReturn.target;$('#import-text').value=importReturn.text;renderImportPreview()}

function wordModal(id,origin=null){stopAudio();const found=findWord(id);if(!found)return;const {word:w,deck}=found;openModal(w.french,'<div class="word-detail"><div class="row between"><div><div class="headword" lang="fr">'+esc(w.french)+'</div><div class="muted">'+esc(w.phonetic)+' · '+esc(w.pos)+'</div></div><button class="button" data-action="say-specific" data-id="'+esc(id)+'" aria-label="'+t('播放单词','Play word','Écouter')+'">'+icon('audio')+'</button></div><div class="meaning">'+esc(w.meaning)+'</div>'+genderAudio(w)+'<div class="usage">'+esc(w.usage)+'</div><div class="source-line" style="margin-top:16px">'+esc(deck.name)+' · '+(dueOf(id)?t('下次复习','Next review','Prochaine révision')+' '+date(dueOf(id)):t('尚未安排复习','Not scheduled yet','Pas encore planifié'))+'</div>'+fullDefinitionButton(w)+contexts(w).map(c=>contextCard(w,c)).join('')+'</div>',btn(t('编辑词条','Edit word','Modifier le mot'),'edit-word','','data-id="'+esc(id)+'"')+btn(t('添加例句 / 音频','Add example / audio','Ajouter exemple / audio'),'add-context','','data-word="'+esc(id)+'"')+btn(t('完成','Done','Terminé'),'close','primary'),false,origin?{origin,shared:true}:null)}
function genderEditorFields(w){return '<div class="gender-editor full"><label class="check-row"><input name="hasGender" type="checkbox" '+(w.hasGender?'checked':'')+'><span>'+t('显示相关阳性 / 阴性词形供参考','Show related masculine / feminine forms','Afficher les formes masculine / féminine associées')+'</span></label><div class="form-grid">'+field(t('阳性形式','Masculine','Masculin'),'masc',w.masc)+field(t('阴性形式','Feminine','Féminin'),'fem',w.fem)+'</div><label class="check-row"><input name="practiceGender" type="checkbox" '+(E.usesGenderPractice(w)?'checked':'')+'><span>'+t('同时练习两种词形（确认适用于重点释义后开启）','Practise both forms (only when both fit the key meaning)','Pratiquer les deux formes (si elles correspondent au sens essentiel)')+'</span></label><p class="license-note">'+t('关闭双词形练习后，使用下方的单一拼写目标（通常与词条一致）；相关词形仍保留供查看和朗读。','With this off, use the single spelling target below, usually the headword. Related forms remain available to view and hear.','Sinon, la réponse unique ci-dessous est utilisée, généralement le mot actuel. Les formes associées restent consultables et audibles.')+'</p></div>'}
