function importReferenceSection(){return '<section class="import-audit-section" aria-labelledby="import-audit-title"><div class="row between wrap"><div><h3 id="import-audit-title">'+t('用原 CSV 核对（可选）','Check against the original CSV (optional)','Comparer au CSV original (facultatif)')+'</h3><p class="license-note">'+t('选择同一次导出的法语助手原文件，核对 AI 是否漏词或改动原文。文件只在本机读取。','Choose the original Assistant export to check for missing words and altered source text. Files are read locally.','Choisissez le CSV Assistant original pour repérer les mots manquants et les modifications du texte source. Lecture locale uniquement.')+'</p></div></div><label class="field" for="import-reference-file"><span class="label">'+t('原始法语助手 CSV','Original Assistant CSV','CSV Assistant original')+'</span><input type="file" id="import-reference-file" accept=".csv,text/csv" aria-describedby="import-reference-status"></label><div class="row between wrap"><span id="import-reference-status" class="license-note" role="status" aria-live="polite"></span>'+btn(t('移除核对文件','Remove reference','Retirer la référence'),'clear-import-reference','text-button small','hidden')+'</div><div id="import-audit-report"></div></section>'}
function updateImportCommit(){const button=$('[data-action="commit-import"]'),m=importModel;if(button&&m)button.disabled=!!m.loading||!!m.referenceLoading||!!m.referenceError||!m.entries.length||!!m.errors.length}
function refreshImportAudit(){const m=importModel;if(!m)return;m.audit=m.reference?window.VocabImportAudit.compare(m.entries,m.reference):null;renderImportAudit()}
function effectiveImportEntries(){const m=importModel;return m.reference&&m.restoreOriginals?window.VocabImportAudit.restoreOriginals(m.entries,m.reference,m.audit):clone(m.entries)}
function renderImportAudit(){
 const focusId=document.activeElement?.id,m=importModel,host=$('#import-audit-report'),status=$('#import-reference-status');if(!m||!host||!status)return;
 const remove=$('[data-action="clear-import-reference"]');if(remove)remove.hidden=!m.referenceName&&!m.referenceError&&!m.referenceLoading;
 status.textContent=m.referenceLoading?t('正在读取原始 CSV…','Reading the original CSV…','Lecture du CSV original…'):m.referenceError|| (m.reference?m.referenceName+' · '+m.reference.rows.length+' '+t('条原始记录','source entries','entrées source'):t('未选择，可直接预览导入。','No reference selected. You can still preview and import.','Sans référence. Vous pouvez prévisualiser et importer.'));
 status.classList.toggle('import-audit-warning',!!m.referenceError);host.innerHTML=m.referenceError?'<p class="import-audit-warning">'+t('请重新选择原始 CSV，或移除核对文件后继续导入。','Choose a valid source CSV, or remove the reference to continue importing.','Choisissez un CSV source valide, ou retirez la référence pour continuer.')+'</p>':'';
 if(!m.reference||m.referenceLoading)return;
 if(!m.entries.length){host.innerHTML='<p class="license-note">'+t('原文件已就绪。上传或粘贴 AI 整理后的词表，再点击“预览与检查”。','Reference ready. Upload or paste the AI-prepared list, then choose Preview & check.','Référence prête. Ajoutez la liste préparée par l’IA, puis prévisualisez-la.')+'</p>';return}
 const a=m.audit||window.VocabImportAudit.compare(m.entries,m.reference),fieldNames={originalMeaning:t('原始释义','Original definition','Définition originale'),originalNotes:t('原始笔记','Original notes','Notes originales')};
 const details=(title,list,describe)=>list.length?'<details class="import-audit-details"><summary>'+title+' · '+list.length+'</summary><ul>'+list.map(x=>'<li>'+esc(describe(x))+'</li>').join('')+'</ul></details>':'';
 host.innerHTML='<div class="import-audit-summary" role="status"><strong>'+t('成功对应原文件','Matched source entries','Entrées source associées')+' '+a.matchedCount+' / '+a.sourceCount+'</strong><span>'+t('当前词表','Current list','Liste actuelle')+' '+a.entryCount+' '+t('条','entries','entrées')+'</span></div><p class="license-note">'+t('只核对词条覆盖和原文，整理后的语义仍需人工抽查。','Checks word coverage and source text only. Prepared meanings still need a human spot-check.','Vérifie uniquement les mots et le texte source. Le sens organisé reste à contrôler manuellement.')+'</p>'
  +details(t('本批未包含','Not in this batch','Absentes de ce lot'),a.missing,x=>x.id+' · '+x.headword)
  +(a.missing.length?'<p class="import-audit-info">'+t('如果正在分批导入，可以继续；导入全量文件时，请核对是否漏词。','A partial batch may be imported. If this is the full list, check for omissions.','Un lot partiel peut être importé. Pour une liste complète, vérifiez les omissions.')+'</p>':'')
  +details(t('原文件中未找到','Not found in source','Introuvables dans la source'),a.extra,x=>x.headword)
  +details(t('需要人工对应','Needs manual matching','Association à vérifier'),a.ambiguous,x=>x.headword+' · '+x.reason)
  +(a.extra.length||a.ambiguous.length?'<p class="import-audit-warning">'+t('以上词条不会自动回填原文，请核对词头、来源序号和参考文件。','These entries will not have source text filled in automatically. Check headwords, source numbers and the reference file.','Le texte source de ces entrées ne sera pas rempli automatiquement. Vérifiez les mots, numéros et fichier de référence.')+'</p>':'')
  +details(t('原文不同或缺失','Changed or missing source text','Texte source modifié ou absent'),a.differences,x=>x.headword+' · '+x.fields.map(f=>fieldNames[f]||f).join('、'))
  +'<label class="check-row import-restore-choice"><input type="checkbox" id="import-restore-originals" '+(m.restoreOriginals?'checked':'')+'><span>'+t('按原 CSV 保留原始释义和笔记','Keep original definitions and notes from the CSV','Conserver les définitions et notes du CSV original')+'</span></label><p class="license-note">'+t('仅回填成功对应的词条，不改动 AI 整理的重点释义、完整释义、用法和例句。完整内容预览会展示实际将保留的原文。','Only safely matched entries are restored. AI-prepared meanings, usage and examples stay unchanged. Full previews show the source text that will be kept.','Seules les associations certaines sont restaurées. Le contenu organisé par l’IA reste inchangé. L’aperçu montre le texte source qui sera conservé.')+'</p>'
  +(!m.restoreOriginals&&a.differences.length?'<p class="import-audit-warning" role="status">'+t('已关闭原文保留：导入后将使用 AI 文件中的原始释义和笔记，其中仍有差异或缺失。','Source preservation is off: the AI file’s source fields will be imported with the differences or omissions shown above.','Conservation désactivée : les champs source du fichier IA seront importés avec les différences ou omissions ci-dessus.')+'</p>':'');
 window.VocabDisclosureMotion?.refresh(host);if(focusId==='import-restore-originals')$('#import-restore-originals')?.focus({preventScroll:true});
}
async function importReferenceFile(file){
 if(!file||!importModel)return;const model=importModel,token=Symbol('reference'),modal=modalRevision;model.referenceToken=token;
 Object.assign(model,{reference:null,audit:null,referenceName:file.name,referenceLoading:true,referenceError:''});renderImportAudit();updateImportCommit();
 const current=()=>importModel===model&&model.referenceToken===token&&modalRevision===modal&&$('#modal').open&&!!$('#import-reference-file');
 try{if(!/\.csv$/i.test(file.name))throw new Error(t('请选择法语助手导出的原始 CSV 文件。','Choose the original CSV exported by Assistant.','Choisissez le CSV original exporté par Assistant.'));if(file.size>12*1024*1024)throw new Error(t('原始 CSV 不能超过 12 MB。','The original CSV must be under 12 MB.','Le CSV original doit faire moins de 12 Mo.'));
  const text=await file.text();if(!current())return;const reference=window.VocabImportAudit.parseSource(text);if(reference.errors.length)throw new Error(reference.errors.map(e=>typeof e==='string'?e:e.message).join(' '));model.reference=reference;
 }catch(error){if(current())model.referenceError=error.message}
 finally{if(importModel===model&&model.referenceToken===token){model.referenceLoading=false;if(current())renderImportPreview()}}
}

