function aboutSection(){return '<section class="about-section"><div><strong>'+t('原作者：凌云_Léo','Original author: 凌云_Léo','Auteur original : 凌云_Léo')+'</strong><p class="license-note">Vocabulaire · 不背法语 · '+esc(RELEASE||'双主题实验版')+'</p></div>'+'<div class="row wrap">'+btn(t('查看入门引导','View getting started','Voir le guide de départ'),'onboarding-replay','small')+btn(t('使用说明与快捷键','Help & shortcuts','Aide et raccourcis'),'help','small')+'</div></section>'}
function helpModal(){openModal(t('使用说明与快捷键','Help & shortcuts','Aide et raccourcis'),'<div class="stack"><p>'+t('新词以短组学习，完成后可选择拼全部或只拼错词。拼写或听写中，灰点代表尚未通过，某一轮首次独立拼对才变绿；错词当场订正，再隔轮复查，全部变绿才结束。复习先独立回忆，再按揭晓前的情况评分。','Learn in short groups, then optionally practise spelling. Rate reviews by what you recalled before revealing.','Apprenez par petits groupes, puis entraînez l’orthographe. Évaluez le rappel avant de voir la réponse.')+'</p><div class="note">'+t('Space / Enter：揭晓、提交、继续<br>1–4：选择选项；评分 Q 认识 / W 模糊 / E 忘记了<br>P：单词发音；S：揭晓后读例句<br>Z：撤销；Esc：关闭弹窗或返回首页<br>输入框内字母快捷键停用，Enter 提交。','Space / Enter: reveal, submit, continue<br>1–4: options; Q Know it / W Unsure / E Forgot<br>P: word; S: revealed example<br>Z: undo; Esc: close or go home<br>Letter shortcuts are off while typing.','Espace / Entrée : révéler, valider, continuer<br>1–4 : choix ; Q Je connais / W Hésitant / E Oublié<br>P : mot ; S : exemple révélé<br>Z : annuler ; Échap : fermer ou accueil<br>Les raccourcis alphabétiques sont désactivés pendant la saisie.')+'</div><p>'+t('拼写题提前播放单词会标记为提示；听写题重播则是正常题目操作。语音取决于设备和浏览器允许情况。','Playing the answer during spelling counts as a hint; replaying dictation does not. Voices depend on the device and browser.','Écouter la réponse en orthographe est un indice, contrairement à la réécoute en dictée.')+'</p><p>'+(PREVIEW?t('预览的词表、进度与音频仅在本次页面会话保留；刷新即重置，正式存档不会被读取或修改。','Preview words, progress and audio last only for this page session. Reloading resets them; saved data is never read or changed.','Les mots, progrès et audios de démonstration ne durent que cette session. Recharger réinitialise la démonstration sans lire ni modifier vos données.'):t('词表、进度和音频保存在此浏览器中。更换文件位置、浏览器或设备前，请先导出完整备份，再在新设备上恢复。','Your words, progress and audio stay in this browser. Export a full backup before moving the file or changing browsers or devices, then restore it there.','Vos mots, progrès et audios restent dans ce navigateur. Exportez une sauvegarde complète avant de déplacer le fichier ou de changer de navigateur ou d’appareil, puis restaurez-la.'))+'</p><p>'+t('基础词表含 50 个词、100 条例句：99 条自编例句使用合成朗读，另有 1 条内置离线真人短句。真人样本：Vion Nicolas · CC BY 2.0 France。','Starter content has 50 words and 100 examples: 99 authored examples use labelled synthesis, and one human recording is embedded offline. Human sample: Vion Nicolas · CC BY 2.0 France.','50 mots et 100 exemples : 99 exemples rédigés avec synthèse vocale et un enregistrement humain intégré hors ligne. Voix : Vion Nicolas · CC BY 2.0 France.')+'</p><p><a href="https://commons.wikimedia.org/wiki/File:Fr-comment-allez%E2%80%90vous.ogg" target="_blank" rel="noreferrer">Shtooka / Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by/2.0/fr/" target="_blank" rel="noreferrer">CC BY 2.0 FR</a></p><p class="author-credit">'+t('原作者：凌云_Léo','Original author: 凌云_Léo','Auteur original : 凌云_Léo')+'</p><p class="license-note">CARNET · ts-fsrs 5.4.2 (MIT) · SheetJS (Apache 2.0) · <a href="https://github.com/mrdoob/three.js/tree/r160" target="_blank" rel="noreferrer">Three.js r160 (MIT)</a> · Cormorant (OFL 1.1)<br>'+t('复习安排会随学习表现逐步调整。','Review schedules adapt to your learning.','Le calendrier de révision s’adapte à votre apprentissage.')+'</p></div>')}
async function seed(){const ok=await change(s=>{const result=D.importEntries(s,window.VocabSeed,{name:t('法语 · 日常起步','French · Everyday beginnings','Français · Premiers pas'),mode:'new'});const next=result.state,deck=next.decks.find(d=>d.id===result.deckId);for(let i=0;i<deck.words.length;i++){const entry=window.VocabSeed[i];if(entry.contexts)next.contexts[deck.words[i].id]=clone(entry.contexts).map(c=>({...c,id:uid('example'),origin:c.type==='tts'&&c.text===entry.example&&c.translation===entry.exampleZh?'default':'custom'}))}return next},{snapshot:true});if(ok)toast(t('50 个基础词已加入，可以开始学习了。','50 starter words added. Ready to learn.','50 mots ajoutés. Vous pouvez commencer.'))}
